<?php
session_start();
include('../../inc/connection.php');
require_once('../cash/funcs.php');
$uid=(int)($_SESSION['user_id']??0);
$shift=(string)get_column('kp_shift','shift','1');
if(!$shift||$shift==='0')$shift=date('Y-m-d');
$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
  $ids=array_values(array_filter(array_map('intval',(array)($_POST['sale_ids']??[]))));
  $mode=(int)($_POST['pay_mode']??0);$amount=(float)($_POST['amount']??0);$tendered=(float)($_POST['tendered']??$amount);
  if(!$ids||$mode<1||$amount<=0){$error='Select bills, a payment mode, and an amount.';}
  else{$in=implode(',',$ids);$total=(float)column_total('kp_sales','amount',"sale_id IN ($in) AND pay_status=2");
    if($amount<$total){$error='The payment is less than the selected bills total.';}
    else{ensure_payment_mode_columns([$mode]);$pid=(int)pay_id();$col='mode'.$mode;$safeShift=mysqli_real_escape_string($connection,$shift);
      $sql="INSERT INTO kp_sale_payment(pay_id,sale_id,user_id,tendered,pay_date,paid_total,type,counter,$col) SELECT '$pid','$in','$uid','$tendered','$safeShift','$total',1,MAX(counter),'$amount' FROM kp_sales WHERE sale_id IN ($in)";
      if(mysqli_query($connection,$sql)){foreach($ids as $sid){$ordUser=(int)get_column('kp_sales','user_id',"sale_id='$sid'");$bill=(float)get_column('kp_sales','amount',"sale_id='$sid'");$ordShift=mysqli_real_escape_string($connection,(string)get_column('kp_sales','shift',"sale_id='$sid'"));mysqli_query($connection,"INSERT INTO kp_sales_paid(pay_id,sale_id,user_id,ord_user,paid_total,ord_date,pay_date) VALUES('$pid','$sid','$uid','$ordUser','$bill','$ordShift','$safeShift')");mysqli_query($connection,"UPDATE kp_sales SET pay_status=1,pay_date='$safeShift' WHERE sale_id='$sid' AND pay_status=2");}$message='Selected bills cleared successfully.';}else $error='Could not save the payment: '.mysqli_error($connection);
    }
  }
}
$waiters=[];$safeShift=mysqli_real_escape_string($connection,$shift);$q=mysqli_query($connection,"SELECT u.user_id,u.username,COUNT(s.sale_id) bills,COALESCE(SUM(s.amount),0) total FROM kp_users u INNER JOIN kp_sales s ON s.user_id=u.user_id WHERE s.shift='$safeShift' AND s.pay_status=2 GROUP BY u.user_id,u.username ORDER BY total DESC");while($q&&($r=mysqli_fetch_assoc($q)))$waiters[]=$r;
$selected=(int)($_GET['waiter']??($_POST['waiter']??0));$where="s.shift='$safeShift' AND s.pay_status=2".($selected>0?" AND s.user_id='$selected'":'');$bills=[];$q=mysqli_query($connection,"SELECT s.sale_id,s.amount,s.counter,u.username FROM kp_sales s LEFT JOIN kp_users u ON u.user_id=s.user_id WHERE $where ORDER BY s.sale_id DESC");while($q&&($r=mysqli_fetch_assoc($q)))$bills[]=$r;
$modes=[];$q=mysqli_query($connection,"SELECT pay_id,name FROM kp_pay_mode WHERE del_status=2 ORDER BY name");while($q&&($r=mysqli_fetch_assoc($q)))$modes[]=$r;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Waiter Bill Clearance</title><style>body{margin:0;background:#f3f7f5;color:#17342a;font:14px Arial}.page{max-width:1100px;margin:auto;padding:18px}.head,.card{background:#fff;border:1px solid #dce9e2;border-radius:8px;padding:16px;margin-bottom:12px}.head{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(120deg,#075b38,#0c8b55);color:#fff}.head h1{margin:0;font-size:23px}.back{color:#fff;text-decoration:none;border:1px solid #ffffff80;padding:9px 13px;border-radius:6px}.waiters{display:flex;gap:8px;overflow:auto}.waiter{min-width:145px;padding:12px;border:1px solid #b9daca;border-radius:7px;background:#f4fbf7;color:#116b42;text-decoration:none}.waiter.active{background:#087b45;color:#fff}.waiter b,.waiter small{display:block}.layout{display:grid;grid-template-columns:1.5fr .8fr;gap:12px}.bill{display:grid;grid-template-columns:34px 1fr auto;gap:9px;align-items:center;padding:10px;border-bottom:1px solid #e7efeb}.bill input{width:18px;height:18px}.bill strong,.bill small{display:block}.bill small{color:#70827a;margin-top:3px}.amount{font-weight:bold;color:#087b45}.total{display:flex;justify-content:space-between;padding:14px 0;font-size:18px;font-weight:bold}.form-control{width:100%;height:40px;border:1px solid #cbded4;border-radius:6px;padding:0 9px;margin:5px 0 10px;box-sizing:border-box}.btn{width:100%;border:0;border-radius:6px;padding:12px;background:#087b45;color:#fff;font-weight:bold}.alert{padding:10px;border-radius:6px;margin-bottom:10px}.ok{background:#e1f7e9;color:#126b3c}.err{background:#ffe8e6;color:#a52c23}@media(max-width:700px){.layout{grid-template-columns:1fr}.head h1{font-size:18px}}</style></head><body><main class="page"><header class="head"><h1>Waiter Bill Clearance</h1><a class="back" href="index.php">Dashboard</a></header><?php if($message):?><div class="alert ok"><?php echo htmlspecialchars($message);?></div><?php endif;?><?php if($error):?><div class="alert err"><?php echo htmlspecialchars($error);?></div><?php endif;?><section class="card"><b>Select waiter</b><div class="waiters"><a class="waiter <?php echo $selected===0?'active':'';?>" href="clearance.php"><b>All Waiters</b><small>All unpaid bills</small></a><?php foreach($waiters as $w):?><a class="waiter <?php echo $selected===$w['user_id']?'active':'';?>" href="?waiter=<?php echo (int)$w['user_id'];?>"><b><?php echo htmlspecialchars($w['username']);?></b><small><?php echo (int)$w['bills'];?> bills · KES <?php echo number_format($w['total'],2);?></small></a><?php endforeach;?></div></section><form method="post"><input type="hidden" name="waiter" value="<?php echo $selected;?>"><div class="layout"><section class="card"><h3>Unpaid bills</h3><?php foreach($bills as $b):?><label class="bill"><input type="checkbox" name="sale_ids[]" value="<?php echo (int)$b['sale_id'];?>" data-amount="<?php echo (float)$b['amount'];?>"><span><strong>Bill #<?php echo (int)$b['sale_id'];?></strong><small><?php echo htmlspecialchars($b['username']??'Unknown');?> · Counter <?php echo (int)$b['counter'];?></small></span><span class="amount">KES <?php echo number_format($b['amount'],2);?></span></label><?php endforeach;?><?php if(!$bills):?><p>No unpaid bills found.</p><?php endif;?></section><section class="card"><h3>Clear selected</h3><div class="total"><span>Total</span><span id="total">KES 0.00</span></div><label>Payment mode<select class="form-control" name="pay_mode" required><option value="">Select mode</option><?php foreach($modes as $m):?><option value="<?php echo (int)$m['pay_id'];?>"><?php echo htmlspecialchars($m['name']);?></option><?php endforeach;?></select></label><label>Amount received<input class="form-control" id="amount" name="amount" inputmode="decimal" required></label><label>Tendered<input class="form-control" name="tendered" inputmode="decimal" required></label><button class="btn" type="submit">Clear Bills</button></section></div></form></main><script>function calc(){var n=0;document.querySelectorAll('input[name="sale_ids[]"]:checked').forEach(function(x){n+=+x.dataset.amount||0});document.getElementById('total').textContent='KES '+n.toLocaleString('en-KE',{minimumFractionDigits:2,maximumFractionDigits:2});document.getElementById('amount').value=n?n.toFixed(2):''}document.querySelectorAll('input[name="sale_ids[]"]').forEach(function(x){x.onchange=calc});</script></body></html>
